<?php $title=nt('search');$q=mb_strtolower(mb_substr(trim((string)($_GET['q']??'')),0,100));?>
<h1><?=e(nt('search'))?></h1><form method="get"><input type="hidden" name="lang" value="<?=e(siteLanguage())?>"><input type="search" name="q" required maxlength="100" value="<?=e($q)?>" aria-label="<?=e(nt('search'))?>"><button><?=e(nt('search'))?></button></form>
<?php if($q):?><section class="network-card"><h2><?=e(scText('Places','מקומות','Места'))?></h2><?php $matches=array_slice(array_filter(scCatalogue(),fn($p)=>mb_strpos(uxPlaceSearchText($p),$q)!==false),0,20);foreach($matches as $place)scPlaceTile($place,true);if(!$matches)echo '<p>'.e(nt('no_posts')).'</p>';?></section><section class="network-card"><h2><?=e(nt('post'))?></h2><form method="get"><input type="hidden" name="lang" value="<?=e(siteLanguage())?>"><input type="hidden" name="q" value="<?=e($q)?>"><label><?=e(nt('post'))?><select name="type"><?php foreach(publicationFilterLabels() as $kind=>$label):?><option value="<?=e($kind)?>" <?=($_GET['type']??'')===$kind?'selected':''?>><?=e($label)?></option><?php endforeach?></select></label><button><?=e(nt('filter'))?></button></form><?php $results=networkFeed(['q'=>$q,'type'=>isset(publicationTypes()[$_GET['type']??''])?$_GET['type']:'','language'=>'all']);foreach($results['rows'] as $r)networkCard($r);if(!$results['rows'])echo '<p>'.e(nt('no_posts')).'</p>';?></section><section class="network-card"><h2><?=e(scText('Travelers','מטיילים','Путешественники'))?></h2><?php $people=socialQuery("SELECT m.id FROM members m LEFT JOIN member_profiles p ON p.member=m.id WHERE m.state='active' AND (instr(unicode_lower(m.handle),?)>0 OR (NOT EXISTS(SELECT 1 FROM social_display_preferences dp WHERE dp.member=m.id AND dp.mode='nickname') AND instr(unicode_lower(COALESCE(p.name,'')),?)>0)) LIMIT 30",[$q,$q])->fetchAll();foreach($people as $person)if(!networkBlocked($u['id']??'',$person['id']))networkAuthor($person['id']);if(!$people)echo '<p>'.e(nt('no_posts')).'</p>';?></section><?php endif?>
